use std::fs;
use std::path::Path;
use std::process::Command;

use super::*;
use crate::testutil::{TempDir, require, write};

const STATIC_GOLDEN: &str = r#"#!/bin/sh
# GENERATED by libc-world; do not edit
set -eu
TRIPLE=x86_64-unknown-ravenbsd
SYSROOT=/w/sysroot
LOG=${RAVEN_WORLD_LOG:-}
COMMON="--target=$TRIPLE --sysroot=$SYSROOT -fuse-ld=lld -D__ravenbsd__=1 -D__unix__=1 -D__unix=1 -Werror=implicit-function-declaration -Werror=int-conversion -Wno-error=incompatible-pointer-types"
mode=link; mflag=0; shared=0; partial=0
for a in "$@"; do
  case $a in
    -c|-S|-E) mode=compile ;;
    -M|-MM) mode=compile; mflag=1 ;;
    -MD|-MMD|-MF|-MT|-MQ) mflag=1 ;;
    -shared) shared=1 ;;
    -r|-Wl,-r) partial=1 ;;
  esac
done
[ -n "$LOG" ] && mkdir -p "$LOG"
if [ "$mode" = compile ]; then
  [ -n "$LOG" ] && echo "compile $*" >> "$LOG/calls.log"
  if [ "$mflag" = 0 ] && [ -n "$LOG" ]; then
    mkdir -p "$LOG/deps"
    exec clang $COMMON "$@" -MD -MF "$LOG/deps/$$.d"
  fi
  exec clang $COMMON "$@"
fi
[ -n "$LOG" ] && echo "link $*" >> "$LOG/calls.log"
if [ "$partial" = 1 ]; then exec clang $COMMON -nostdlib "$@"; fi
if [ "$shared" = 1 ]; then exec clang $COMMON -nostdlib -nostartfiles -shared "$@" -L"$SYSROOT/usr/lib" -Wl,--error-limit=0 -Wl,-z,max-page-size=4096; fi
BUILTINS=
[ -f "$SYSROOT/usr/lib/libclang_rt.builtins.a" ] && BUILTINS=-lclang_rt.builtins
exec clang $COMMON -nostdlib -nostartfiles -static -Wl,--error-limit=0 -Wl,-z,max-page-size=4096 \
  "$SYSROOT/usr/lib/crt1.o" "$SYSROOT/usr/lib/crti.o" "$@" -L"$SYSROOT/usr/lib" -lc $BUILTINS "$SYSROOT/usr/lib/crtn.o"
"#;

#[test]
fn the_static_x86_64_wrapper_matches_the_golden() {
    assert_eq!(
        wrapper_script("x86_64", Path::new("/w/sysroot"), LinkMode::Static),
        STATIC_GOLDEN
    );
}

#[test]
fn the_dynamic_wrapper_uses_scrt1_and_pie() {
    let script = wrapper_script("aarch64", Path::new("/w/sysroot"), LinkMode::Dynamic);
    assert!(script.contains("TRIPLE=aarch64-unknown-ravenbsd"));
    assert!(script.contains("Scrt1.o"));
    assert!(!script.contains("usr/lib/crt1.o"));
    assert!(script.contains("-pie"));
    assert!(script.contains("-Wl,-dynamic-linker,/libexec/ld-elf.so.1"));
    assert!(script.contains("-L\"$SYSROOT/lib\""));
    assert!(!script.contains("BUILTINS"));
}

#[test]
fn the_static_wrapper_has_the_builtins_guard() {
    let script = wrapper_script("riscv64", Path::new("/w/sysroot"), LinkMode::Static);
    assert!(script.contains("libclang_rt.builtins.a"));
    assert!(script.contains("-static"));
    assert!(script.contains("\"$SYSROOT/usr/lib/crt1.o\""));
}

#[test]
fn the_wrapper_header_says_generated() {
    let script = wrapper_script("x86_64", Path::new("/w/sysroot"), LinkMode::Static);
    assert_eq!(script.lines().next(), Some("#!/bin/sh"));
    assert_eq!(
        script.lines().nth(1),
        Some("# GENERATED by libc-world; do not edit")
    );
}

#[test]
fn the_wrapper_never_inherits_a_host_target_define() {
    let script = wrapper_script("x86_64", Path::new("/w/sysroot"), LinkMode::Static);
    assert!(script.contains("-D__unix__=1"));
    assert!(script.contains("-D__ravenbsd__=1"));
    assert!(!script.contains("-D_GNU_SOURCE"));
}

#[test]
fn the_wrapper_forces_the_two_warnings() {
    let script = wrapper_script("x86_64", Path::new("/w/sysroot"), LinkMode::Static);
    assert!(script.contains("-Werror=implicit-function-declaration"));
    assert!(script.contains("-Werror=int-conversion"));
    assert!(script.contains("-Wno-error=incompatible-pointer-types"));
}

#[test]
fn the_wrapper_has_all_five_invocation_classifiers() {
    let script = wrapper_script("x86_64", Path::new("/w/sysroot"), LinkMode::Static);
    for token in [
        "-c|-S|-E",
        "-M|-MM",
        "-MD|-MMD|-MF|-MT|-MQ",
        "-shared",
        "-r|-Wl,-r",
    ] {
        assert!(script.contains(token), "{token}");
    }
}

#[test]
fn write_wrapper_sets_the_executable_bit() {
    use std::os::unix::fs::PermissionsExt as _;
    let temp = TempDir::new("wrapper-write");
    let path = temp.join("bin/raven-cc");
    write_wrapper(&path, "x86_64", Path::new("/w/sysroot"), LinkMode::Static).expect("write");
    let mode = fs::metadata(&path).expect("meta").permissions().mode();
    assert_eq!(mode & 0o111, 0o111);
    assert_eq!(fs::read_to_string(&path).expect("read"), STATIC_GOLDEN);
}

#[test]
fn a_link_mode_parses_both_values() {
    assert_eq!(LinkMode::parse("static"), Some(LinkMode::Static));
    assert_eq!(LinkMode::parse("dynamic"), Some(LinkMode::Dynamic));
    assert_eq!(LinkMode::parse("shared"), None);
    assert_eq!(LinkMode::Static.as_str(), "static");
    assert_eq!(LinkMode::Dynamic.as_str(), "dynamic");
}

#[test]
fn the_toolchain_cmake_matches_the_golden() {
    let text = toolchain_cmake(
        "x86_64",
        Path::new("/w/out/x86_64/bin/raven-cc"),
        Path::new("/w/sysroot"),
    );
    let expected = r#"set(CMAKE_SYSTEM_NAME Generic)
set(CMAKE_SYSTEM_PROCESSOR x86_64)
set(CMAKE_C_COMPILER /w/out/x86_64/bin/raven-cc)
set(CMAKE_C_COMPILER_TARGET x86_64-unknown-ravenbsd)
set(CMAKE_SYSROOT /w/sysroot)
set(CMAKE_TRY_COMPILE_TARGET_TYPE STATIC_LIBRARY)
set(CMAKE_FIND_ROOT_PATH_MODE_PROGRAM NEVER)
set(CMAKE_FIND_ROOT_PATH_MODE_LIBRARY ONLY)
set(CMAKE_FIND_ROOT_PATH_MODE_INCLUDE ONLY)
set(UNIX 1)
"#;
    assert_eq!(text, expected);
}

fn fake_clang(temp: &TempDir) -> std::path::PathBuf {
    let bin = temp.join("bin");
    fs::create_dir_all(&bin).expect("bin");
    let clang = bin.join("clang");
    write(
        &clang,
        "#!/bin/sh\nprintf '%s\\n' \"$@\" > \"$ARGS_FILE\"\n",
    );
    use std::os::unix::fs::PermissionsExt as _;
    let mut permissions = fs::metadata(&clang).expect("meta").permissions();
    permissions.set_mode(0o755);
    fs::set_permissions(&clang, permissions).expect("chmod");
    bin
}

fn run_wrapper(temp: &TempDir, args: &[&str]) -> Vec<String> {
    let args_file = temp.join("args.txt");
    let output = Command::new("sh")
        .arg(temp.join("raven-cc"))
        .args(args)
        .env(
            "PATH",
            format!(
                "{}:{}",
                temp.join("bin").display(),
                std::env::var("PATH").unwrap_or_default()
            ),
        )
        .env("ARGS_FILE", &args_file)
        .env("RAVEN_WORLD_LOG", temp.join("log"))
        .output()
        .expect("wrapper");
    assert!(
        output.status.success(),
        "{}",
        String::from_utf8_lossy(&output.stderr)
    );
    fs::read_to_string(&args_file)
        .expect("args")
        .lines()
        .map(str::to_string)
        .collect()
}

#[test]
fn a_compile_invocation_gets_md_and_mf() {
    if !require(&["sh"]) {
        return;
    }
    let temp = TempDir::new("wrapper-sh-compile");
    fake_clang(&temp);
    let path = temp.join("raven-cc");
    write_wrapper(&path, "x86_64", Path::new("/w/sysroot"), LinkMode::Static).expect("write");
    let args = run_wrapper(&temp, &["-c", "a.c", "-o", "a.o"]);
    assert_eq!(
        args.first().map(String::as_str),
        Some("--target=x86_64-unknown-ravenbsd")
    );
    assert!(args.contains(&"-c".to_string()));
    assert!(args.contains(&"-MD".to_string()));
    assert!(args.contains(&"-MF".to_string()));
    let mf = args.iter().position(|arg| arg == "-MF").expect("mf");
    assert!(args[mf + 1].ends_with(".d"));
    let calls = fs::read_to_string(temp.join("log/calls.log")).expect("calls");
    assert!(calls.starts_with("compile -c a.c -o a.o"));
}

#[test]
fn an_mmd_compile_gets_no_extra_md() {
    if !require(&["sh"]) {
        return;
    }
    let temp = TempDir::new("wrapper-sh-mmd");
    fake_clang(&temp);
    let path = temp.join("raven-cc");
    write_wrapper(&path, "x86_64", Path::new("/w/sysroot"), LinkMode::Static).expect("write");
    let args = run_wrapper(&temp, &["-c", "a.c", "-MMD", "-MF", "deps.d"]);
    assert_eq!(args.iter().filter(|arg| *arg == "-MD").count(), 0);
    assert_eq!(args.iter().filter(|arg| *arg == "-MF").count(), 1);
}

#[test]
fn a_static_link_drives_the_link_itself() {
    if !require(&["sh"]) {
        return;
    }
    let temp = TempDir::new("wrapper-sh-static");
    fake_clang(&temp);
    let path = temp.join("raven-cc");
    write_wrapper(&path, "x86_64", Path::new("/w/sysroot"), LinkMode::Static).expect("write");
    let args = run_wrapper(&temp, &["-o", "prog", "a.o", "-lm"]);
    assert!(args.contains(&"-nostdlib".to_string()));
    assert!(args.contains(&"-nostartfiles".to_string()));
    assert!(args.contains(&"-static".to_string()));
    assert!(args.contains(&"/w/sysroot/usr/lib/crt1.o".to_string()));
    assert!(args.contains(&"/w/sysroot/usr/lib/crti.o".to_string()));
    assert!(args.contains(&"/w/sysroot/usr/lib/crtn.o".to_string()));
    assert!(args.contains(&"-lc".to_string()));
    assert!(args.contains(&"-Wl,--error-limit=0".to_string()));
    assert!(args.contains(&"-Wl,-z,max-page-size=4096".to_string()));
    assert!(
        args.windows(2)
            .any(|pair| pair[0] == "-o" && pair[1] == "prog")
    );
    assert!(args.contains(&"-lm".to_string()));
}

